# typed: strict
# frozen_string_literal: true

# Homebrew formula for the Superopen CLI (`so`).
#
# Generated by ishanjainn/superopen's Release / Packages workflow.
# Manual install: brew install ishanjainn/superopen/so
class So < Formula
  desc "Native code graph and coding-session observability"
  homepage "https://github.com/ishanjainn/superopen"
  version "0.9.1"
  license "Apache-2.0"

  head do
    url "https://github.com/ishanjainn/superopen.git", branch: "main"
    depends_on "go" => :build
  end

  on_macos do
    on_arm do
      url "https://github.com/ishanjainn/superopen/releases/download/cli-0.9.1/so-darwin-arm64.tar.gz"
      sha256 "a4c56ac6fda6cbbed7ee9383a74274ade6f47d95ffebee819bc2b50332a9b99b"
    end
    on_intel do
      url "https://github.com/ishanjainn/superopen/releases/download/cli-0.9.1/so-darwin-amd64.tar.gz"
      sha256 "e20420b620c0edb1771382172484ce146b5ffa803b2df21974e547e04d71ade6"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ishanjainn/superopen/releases/download/cli-0.9.1/so-linux-arm64.tar.gz"
      sha256 "565057c29e4fa38604e83e7eff00e026155e64f1f42099b066cc048874237c8f"
    end
    on_intel do
      url "https://github.com/ishanjainn/superopen/releases/download/cli-0.9.1/so-linux-amd64.tar.gz"
      sha256 "5b7361d9341313b45f559a6d5798fc4cbd851cd56f342969c392830a2ca987cd"
    end
  end

  resource "web" do
    url "https://github.com/ishanjainn/superopen/releases/download/cli-0.9.1/so-web.tar.gz"
    sha256 "bd3a8f8160d38fb42ac66351a554053d6cdfe5c022e72a9d5a2dc50e5d99273e"
  end

  depends_on "node"

  def install
    if build.head?
      system "go", "build", "-o", bin/"so", "./cmd/so"
      log = buildpath/"web-build.log"
      cd "web" do
        cmd = "npm install --ignore-scripts >>#{log} 2>&1 && npm run build >>#{log} 2>&1"
        unless quiet_system("sh", "-c", cmd)
          odie "UI build failed. See #{log}"
        end
      end
      standalone = buildpath/"web/.next/standalone"
      odie "web UI standalone build missing" unless (standalone/"server.js").exist?
      static_dir = buildpath/"web/.next/static"
      if static_dir.exist?
        (standalone/".next/static").mkpath
        static_dir.children.each { |child| cp_r child, standalone/".next/static"/child.basename }
      end
      public_dir = buildpath/"web/public"
      if public_dir.exist?
        (standalone/"public").mkpath
        public_dir.children.each { |child| cp_r child, standalone/"public"/child.basename }
      end
      dst = share/"superopen/web"
      dst.mkpath
      standalone.children.each { |child| cp_r child, dst/child.basename }
    else
      bin.install Dir["so*"].first => "so"
      resource("web").stage do
        dst = share/"superopen/web"
        dst.mkpath
        Pathname(".").children.each { |child| cp_r child, dst/child.basename }
      end
    end
  end

  def caveats
    <<~EOS
      Run `so install` once to wire coding-agent hooks.
      Then in any repo: `so init` and `so dev`.
      `so dev` needs Node.js (already installed as a dependency).
    EOS
  end

  test do
    assert_match "so", shell_output("#{bin}/so --help")
  end
end
